fn hex_decode(hex: &str) -> Result<Vec<u8>> {
    let bytes = hex.as_bytes();
    if !bytes.len().is_multiple_of(2) {
        return Err(anyhow!("hex string has an odd length"));
    }
    if !bytes.iter().all(u8::is_ascii_hexdigit) {
        return Err(anyhow!("hex string has a non-hex character (zanary-receipt-v1 says lowercase hex)"));
    }
    (0..bytes.len())
        .step_by(2)
        .map(|i| {
            u8::from_str_radix(&hex[i..i + 2], 16)
                .map_err(|e| anyhow!("invalid hex at byte {}: {e}", i / 2))
        })
        .collect()
}

/// The first char boundary at byte offset >= n (or `s.len()`), so `short` never
/// slices inside a multi-byte character.
fn at_byte(s: &str, n: usize) -> usize {
    s.char_indices()
        .map(|(i, _)| i)
        .chain(std::iter::once(s.len()))
        .find(|&i| i >= n)
        .unwrap_or(s.len())
}

pub fn short(hex: &str) -> String {
    if hex.len() > 20 {
        let head = at_byte(hex, 8);
        let tail_start = at_byte(hex, hex.len() - 8);
        format!("{}…{}", &hex[..head], &hex[tail_start..])
    } else {
        hex.to_string()
    }
}

/// True when `words` states `needle` as a whole token (a claim may not merely embed it).
fn states(words: &str, needle: &str) -> bool {
    words.match_indices(needle).any(|(start, _)| {
        let before_ok = words[..start]
            .chars()
            .next_back()
            .is_none_or(|c| !c.is_ascii_alphanumeric());
        let after_ok = words[start + needle.len()..]
            .chars()
            .next()
            .is_none_or(|c| !c.is_ascii_alphanumeric());
        before_ok && after_ok
    })
}

